// Client-side, offline PPTX slide rasterizer. Basic text, shape, image support.
const xml=s=>new DOMParser().parseFromString(s,'application/xml');
// e may be missing (text without run properties, placeholders without their own position): nothing found then.
const children=(e,name)=>e?[...e.getElementsByTagName('*')].filter(n=>n.localName===name):[];
const first=(e,name)=>children(e,name)[0];
const attr=(e,name)=>e?.getAttribute(name)||'';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function bytesToText(b){return new TextDecoder().decode(b)}
async function archive(file){const b=new Uint8Array(await file.arrayBuffer()),view=new DataView(b.buffer),out=new Map();let eoc=-1;for(let i=b.length-22;i>=Math.max(0,b.length-65557);i--)if(view.getUint32(i,true)===0x06054b50){eoc=i;break}if(eoc<0)throw Error('PPTX ZIPの索引を取得できません');let ptr=view.getUint32(eoc+16,true),count=view.getUint16(eoc+10,true);if(count>20000)throw Error('ZIP内ファイルが多すぎます');for(let i=0;i<count;i++){if(view.getUint32(ptr,true)!==0x02014b50)throw Error('ZIP索引が不正です');const method=view.getUint16(ptr+10,true),sz=view.getUint32(ptr+20,true),nameLen=view.getUint16(ptr+28,true),extra=view.getUint16(ptr+30,true),comment=view.getUint16(ptr+32,true),local=view.getUint32(ptr+42,true);const name=bytesToText(b.slice(ptr+46,ptr+46+nameLen));ptr+=46+nameLen+extra+comment;if(!name.startsWith('ppt/'))continue;if(sz>70*1024*1024)throw Error('巨大なファイルを含むPPTXは対応外です');if(view.getUint32(local,true)!==0x04034b50)throw Error('ZIPのデータ位置が不正です');const dataStart=local+30+view.getUint16(local+26,true)+view.getUint16(local+28,true);const data=b.slice(dataStart,dataStart+sz);if(method===0)out.set(name,data);else if(method===8){const stream=new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'));out.set(name,new Uint8Array(await new Response(stream).arrayBuffer()))}else throw Error('未対応のZIP圧縮方式です')}return out}
function norm(path){const a=[];for(const p of path.split('/')){if(p==='..')a.pop();else if(p&&p!=='.')a.push(p)}return a.join('/')}
function fillOf(node){const solid=first(node,'solidFill');if(!solid)return null;const rgb=first(solid,'srgbClr');if(rgb)return '#'+attr(rgb,'val');const scheme=first(solid,'schemeClr');const colors={dk1:'#161616',lt1:'#ffffff',accent1:'#4676b8',accent2:'#e0765a',accent3:'#7fa85a',accent4:'#9b6bb0',tx1:'#141414',bg1:'#ffffff'};return colors[attr(scheme,'val')]||'#444444'}
function geom(n){const x=first(n,'xfrm');const off=first(x,'off'),ext=first(x,'ext');return {x:+attr(off,'x')||0,y:+attr(off,'y')||0,w:+attr(ext,'cx')||0,h:+attr(ext,'cy')||0,rot:(+attr(x,'rot')||0)/60000}}
function textParts(n){return children(n,'p').map(p=>children(p,'t').map(t=>t.textContent||'').join('')).filter(Boolean)}
function shape(n,sx,sy){const g=geom(n),x=g.x*sx,y=g.y*sy,w=g.w*sx,h=g.h*sy;if(!w||!h)return '';const pr=first(n,'spPr')||n,c=fillOf(pr)||'#ffffff',shapeType=attr(first(pr,'prstGeom'),'prst'),a=textParts(n),rotation=g.rot?` transform="rotate(${g.rot} ${x+w/2} ${y+h/2})"`:'';let s='';if(shapeType==='ellipse')s=`<ellipse cx="${x+w/2}" cy="${y+h/2}" rx="${w/2}" ry="${h/2}" fill="${c}"/>`;else s=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${c}"/>`;if(a.length){const r=first(n,'rPr')||first(n,'endParaRPr'),size= Math.min(96,Math.max(14,(+attr(r,'sz')||2600)/100*1280/960));const textColor=fillOf(r)||'#111111';s+=a.map((t,i)=>`<text x="${x+Math.max(10,w*.04)}" y="${y+Math.min(h-4,Math.max(size,i*size*1.22+size))}" font-size="${size}" font-family="Arial,sans-serif" fill="${textColor}">${esc(t)}</text>`).join('')}return `<g${rotation}>${s}</g>`}
function imageB64(data){let str='';for(let i=0;i<data.length;i+=8192)str+=String.fromCharCode(...data.subarray(i,i+8192));return btoa(str)}
async function makeSlide(doc,relationship,files,cx,cy,number){const width=1280,height=720,sx=width/cx,sy=height/cy;const relMap=new Map();for(const r of children(relationship,'Relationship'))relMap.set(attr(r,'Id'),norm(`ppt/slides/${attr(r,'Target')}`));const tree=first(doc,'spTree');const parts=[];for(const n of [...tree.children]){if(n.localName==='sp'){parts.push(shape(n,sx,sy))}else if(n.localName==='pic'){const blip=first(n,'blip');const rid=blip?.getAttribute('r:embed')||[...blip?.attributes||[]].find(a=>a.localName==='embed')?.value;const key=relMap.get(rid);const buf=files.get(key);if(!buf)continue;const ext=key.split('.').pop().toLowerCase(),mime={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp'}[ext];if(!mime)continue;const g=geom(n),x=g.x*sx,y=g.y*sy,w=g.w*sx,h=g.h*sy;parts.push(`<image x="${x}" y="${y}" width="${w}" height="${h}" href="data:${mime};base64,${imageB64(buf)}" preserveAspectRatio="xMidYMid meet"/>`)}}
const svg=`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><rect width="100%" height="100%" fill="white"/>${parts.join('')}</svg>`;const blob=new Blob([svg],{type:'image/svg+xml'}),url=URL.createObjectURL(blob);try{const im=new Image();await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=reject;im.src=url});const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;canvas.getContext('2d').drawImage(im,0,0,width,height);const png=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!png)throw Error('スライド画像の生成に失敗');return new File([png],`slide-${String(number).padStart(3,'0')}.png`,{type:'image/png'})}finally{URL.revokeObjectURL(url)}}
export async function pptxToImages(file){if(!/\.pptx$/i.test(file.name))throw Error('PPTXファイルを選択してください');if(!globalThis.DecompressionStream)throw Error('このブラウザはPPTX解凍に対応していません');const files=await archive(file),presentation=xml(bytesToText(files.get('ppt/presentation.xml')||new Uint8Array()));const ext=first(presentation,'sldSz'),cx=+attr(ext,'cx')||12192000,cy=+attr(ext,'cy')||6858000;const slides=[...files.keys()].filter(x=>/^ppt\/slides\/slide\d+\.xml$/.test(x)).sort((a,b)=>+a.match(/slide(\d+)/)[1]- +b.match(/slide(\d+)/)[1]);if(!slides.length)throw Error('スライドがありません');if(slides.length>300)throw Error('最大300枚まで対応します');const result=[];for(let i=0;i<slides.length;i++){const p=slides[i],base=p.replace(/slide(\d+)\.xml$/,'_rels/slide$1.xml.rels');result.push(await makeSlide(xml(bytesToText(files.get(p))),xml(bytesToText(files.get(base)||new Uint8Array())),files,cx,cy,i+1))}return result}
